#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <numeric>
#include <vector>
struct V{double x,y,z;V operator+(V b)const{return{x+b.x,y+b.y,z+b.z};}V operator-(V b)const{return{x-b.x,y-b.y,z-b.z};}V operator*(double s)const{return{x*s,y*s,z*s};}double operator[](int k)const{return k==0?x:k==1?y:z;}};
double dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
struct Tri{V a,b,c,lo,hi;double s[3];};
struct Node{V lo,hi;int l=-1,r=-1,first,count;};
std::vector<Tri>tris;std::vector<uint32_t>order;std::vector<Node>nodes;
int build(int first,int count){Node n; n.lo={1e100,1e100,1e100};n.hi={-1e100,-1e100,-1e100};n.first=first;n.count=count;for(int i=first;i<first+count;i++){auto&t=tris[order[i]];n.lo={std::min(n.lo.x,t.lo.x),std::min(n.lo.y,t.lo.y),std::min(n.lo.z,t.lo.z)};n.hi={std::max(n.hi.x,t.hi.x),std::max(n.hi.y,t.hi.y),std::max(n.hi.z,t.hi.z)};}int id=nodes.size();nodes.push_back(n);if(count>12){V d=n.hi-n.lo;int ax=d.x>d.y?(d.x>d.z?0:2):(d.y>d.z?1:2),mid=first+count/2;std::nth_element(order.begin()+first,order.begin()+mid,order.begin()+first+count,[&](auto a,auto b){return tris[a].lo[ax]+tris[a].hi[ax]<tris[b].lo[ax]+tris[b].hi[ax];});int l=build(first,mid-first),r=build(mid,first+count-mid);nodes[id].l=l;nodes[id].r=r;}return id;}
double aabb(V p,const Node&n){double d=0;for(int j=0;j<3;j++){double x=std::max({n.lo[j]-p[j],0.,p[j]-n.hi[j]});d+=x*x;}return d;}
std::array<double,3> closest(V p,const Tri&t){V ab=t.b-t.a,ac=t.c-t.a,ap=p-t.a;double d1=dot(ab,ap),d2=dot(ac,ap);if(d1<=0&&d2<=0)return{1,0,0};V bp=p-t.b;double d3=dot(ab,bp),d4=dot(ac,bp);if(d3>=0&&d4<=d3)return{0,1,0};double vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0){double v=d1/(d1-d3);return{1-v,v,0};}V cp=p-t.c;double d5=dot(ab,cp),d6=dot(ac,cp);if(d6>=0&&d5<=d6)return{0,0,1};double vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0){double w=d2/(d2-d6);return{1-w,0,w};}double va=d3*d6-d5*d4;if(va<=0&&(d4-d3)>=0&&(d5-d6)>=0){double w=(d4-d3)/((d4-d3)+(d5-d6));return{0,1-w,w};}double inv=1/(va+vb+vc),v=vb*inv,w=vc*inv;return{1-v-w,v,w};}
void search(int id,V p,double&best,double&value){const Node&n=nodes[id];if(aabb(p,n)>best)return;if(n.l<0){for(int i=n.first;i<n.first+n.count;i++){const auto&t=tris[order[i]];auto w=closest(p,t);V q=t.a*w[0]+t.b*w[1]+t.c*w[2];double d=dot(p-q,p-q);if(d<best){best=d;value=w[0]*t.s[0]+w[1]*t.s[1]+w[2]*t.s[2];}}}else{double l=aabb(p,nodes[n.l]),r=aabb(p,nodes[n.r]);if(l<r){search(n.l,p,best,value);search(n.r,p,best,value);}else{search(n.r,p,best,value);search(n.l,p,best,value);}}}
struct Tet{V o,g1,g2,g3,lo,hi;double s[4];};
std::vector<Tet>tets;std::vector<uint32_t>to;std::vector<Node>tn;
V cross(V a,V b){return{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x};}
int buildT(int first,int count){Node n;n.lo={1e100,1e100,1e100};n.hi={-1e100,-1e100,-1e100};n.first=first;n.count=count;for(int i=first;i<first+count;i++){auto&t=tets[to[i]];n.lo={std::min(n.lo.x,t.lo.x),std::min(n.lo.y,t.lo.y),std::min(n.lo.z,t.lo.z)};n.hi={std::max(n.hi.x,t.hi.x),std::max(n.hi.y,t.hi.y),std::max(n.hi.z,t.hi.z)};}int id=tn.size();tn.push_back(n);if(count>12){V d=n.hi-n.lo;int ax=d.x>d.y?(d.x>d.z?0:2):(d.y>d.z?1:2),mid=first+count/2;std::nth_element(to.begin()+first,to.begin()+mid,to.begin()+first+count,[&](auto a,auto b){return tets[a].lo[ax]+tets[a].hi[ax]<tets[b].lo[ax]+tets[b].hi[ax];});int l=buildT(first,mid-first),r=buildT(mid,first+count-mid);tn[id].l=l;tn[id].r=r;}return id;}
bool contains(int id,V p,double&v){const auto&n=tn[id];if(p.x<n.lo.x-1e-9||p.x>n.hi.x+1e-9||p.y<n.lo.y-1e-9||p.y>n.hi.y+1e-9||p.z<n.lo.z-1e-9||p.z>n.hi.z+1e-9)return false;if(n.l>=0)return contains(n.l,p,v)||contains(n.r,p,v);for(int j=n.first;j<n.first+n.count;j++){const auto&t=tets[to[j]];V q=p-t.o;double b=dot(t.g1,q),c=dot(t.g2,q),d=dot(t.g3,q),a=1-b-c-d;if(std::min({a,b,c,d})>=-1e-8){v=a*t.s[0]+b*t.s[1]+c*t.s[2]+d*t.s[3];return true;}}return false;}
int main(int argc,char**argv){if(argc!=3)return 2;std::ifstream in(argv[1],std::ios::binary);uint32_t nv,nf,nt;in.read((char*)&nv,4);in.read((char*)&nf,4);in.read((char*)&nt,4);std::vector<V>p(nv);std::vector<double>s(nv);std::vector<uint32_t>f(3ull*nf),tt(4ull*nt);in.read((char*)p.data(),nv*sizeof(V));in.read((char*)s.data(),nv*8ull);in.read((char*)f.data(),nf*12ull);in.read((char*)tt.data(),nt*16ull);if(!in)return 3;for(uint32_t i=0;i<nf;i++){auto a=f[3*i],b=f[3*i+1],c=f[3*i+2];auto A=p[a],B=p[b],C=p[c];tris.push_back({A,B,C,{std::min({A.x,B.x,C.x}),std::min({A.y,B.y,C.y}),std::min({A.z,B.z,C.z})},{std::max({A.x,B.x,C.x}),std::max({A.y,B.y,C.y}),std::max({A.z,B.z,C.z})},{s[a],s[b],s[c]}});}order.resize(nf);std::iota(order.begin(),order.end(),0);build(0,nf);for(uint32_t i=0;i<nt;i++){auto a=tt[4*i],b=tt[4*i+1],c=tt[4*i+2],d=tt[4*i+3];V A=p[a],B=p[b],C=p[c],D=p[d],e1=B-A,e2=C-A,e3=D-A;double det=dot(e1,cross(e2,e3));tets.push_back({A,cross(e2,e3)*(1/det),cross(e3,e1)*(1/det),cross(e1,e2)*(1/det),{std::min({A.x,B.x,C.x,D.x}),std::min({A.y,B.y,C.y,D.y}),std::min({A.z,B.z,C.z,D.z})},{std::max({A.x,B.x,C.x,D.x}),std::max({A.y,B.y,C.y,D.y}),std::max({A.z,B.z,C.z,D.z})},{s[a],s[b],s[c],s[d]}});}to.resize(nt);std::iota(to.begin(),to.end(),0);buildT(0,nt);double cutoff=std::stod(argv[2]);uint32_t n;while(std::cin.read((char*)&n,4)){std::vector<V>q(n);std::cin.read((char*)q.data(),n*sizeof(V));std::vector<float>out(2ull*n);for(uint32_t i=0;i<n;i++){double value=0,best=0;bool inside=contains(0,q[i],value);if(!inside){best=1e100;search(0,q[i],best,value);}out[i]=inside||std::sqrt(best)<=cutoff?(float)std::max(0.,value):NAN;out[n+i]=std::sqrt(best);}std::cout.write((char*)out.data(),out.size()*4);std::cout.flush();}return 0;}
